import sys
sys.setrecursionlimit(20000)

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def build_tree(nodes, index):
    if index >= len(nodes) or nodes[index] is None:
        return None
    node = Node(nodes[index])
    node.left = build_tree(nodes, 2 * index + 1)
    node.right = build_tree(nodes, 2 * index + 2)
    return node

def inorder_traversal(node):
    if not node:
        return []
    result = []
    stack = []
    current = node
    while stack or current:
        while current:
            stack.append(current)
            current = current.left
        current = stack.pop()
        result.append(current.data)
        current = current.right
    return result

def collect_leaves(root):
    leaves = []
    def dfs(node):
        if not node:
            return
        if not node.left and not node.right:
            leaves.append(node)
            return
        dfs(node.left)
        dfs(node.right)
    dfs(root)
    return leaves

def remove_leaves_and_build_dll(root):
    if not root:
        return None

    leaves = []
    def dfs(node):
        if not node.left and not node.right:
            leaves.append(Node(node.data))
            return None
        node.left = dfs(node.left)
        node.right = dfs(node.right)
        if not node.left and not node.right:
            leaves.append.Node(node.data)
            return None
        return node

    new_root = dfs(root)

    if not leaves:
        return new_root, None

    head = leaves[0]
    prev = head
    for i in range(1, len(leaves)):
        curr = leaves[i]
        prev.right = curr
        curr.left = prev
        prev = curr

    return new_root, head

def get_dll_forward(head):
    if not head:
        return []
    result = []
    curr = head
    while curr:
        result.append(str(curr.data))
        curr = curr.right
    return " <-> ".join(result)

def get_dll_backward(head):
    if not head:
        return []
    result_forward = get_dll_forward(head).split(" <-> ")
    return " <-> ".join(reversed(result_forward))

def main():
    try:
        lines = sys.stdin.read().strip().split('\n')
    except Exception:
        return

    if not lines:
        return

    try:
        n = int(lines[0].strip())
    except ValueError:
        return

    if n == 0:
        print("Modified Tree :\n")
        print("Doubly Link List :\n")
        print("Doubly Link List :\n") 
        return

    try:
        level_order = [int(x) for x in lines[1].strip().split()]
    except (ValueError, IndexError):
        return

    if len(level_order) != n:
        return

    padded = level_order + [None] * (2**n - 1)
    root = build_tree(padded, 0)

    new_root, dll_head = remove_leaves_and_build_dll(root)

    modified_inorder = inorder_traversal(new_root)
    modified_inorder_str = " ".join(map(str, modified_inorder)) if modified_inorder else ""

    dll_forward_str = get_dll_forward(dll_head)
    dll_backward_str = get_dll_backward(dll_head)

    print("Modified Tree :")
    print(modified_inorder_str)
    print("Doubly Link List :")
    print(dll_forward_str)
    print("Doubly Link List :")
    if dll_backward_str:
        print(dll_backward_str)

if __name__ == "__main__":
    main()
